  function librarianCardBody() { return $('manage-librarian-card-body'); }

  // ⚠ GATED ON `librarian.available` AT ITS OWN TOP for the run-flavored
  // half, which is the gate that used to sit in refreshLibrarianSettings
  // beside the slot. ⛔ The DISCLOSURE half above it is deliberately
  // ungated — T-26-17's surviving reason: it must still render while
  // `available` is false, or it is a consent nobody could reach.
  function fillLibrarianDetail(host, librarian) {
    if (!host) { return; }
    renderLibrarianSettings(host, librarian, LIBRARIAN_SCOPE_CARD);
    if (!librarian) { return; }
    if (librarian.available === true) {
      readLibrarianRunState(host.querySelector('.librarian-run-state'));
    }
    renderJobDisclosure(host.querySelector('.librarian-job-list'));
  }

  function dismissLibrarianCard() {
    var raised = $('manage-librarian-card');
    if (raised && raised.parentNode) {
      raised.parentNode.removeChild(raised);
    }
  }

  // ⚠ RAISE, never toggle — and that is the door's shape rather than a
  // simplification. The desk objects toggle because a second tap on the
  // object is reachable; this door is a row in an overlay that closes the
  // moment it is picked, so a toggle arm could never be reached and would
  // be a branch nothing can drive. The ✕ is the way out.
  function raiseLibrarianCard() {
    dismissLibrarianCard();
    var screen = $('screen-manage');
    if (!screen) { return; }
    var card = document.createElement('div');
    card.id = 'manage-librarian-card';
    card.className = 'card manage-librarian-card';
    var close = document.createElement('button');
    close.type = 'button';
    close.className = 'manage-librarian-card-close';
    close.setAttribute('aria-label', 'close');
    close.textContent = '×';
    close.addEventListener('click', dismissLibrarianCard);
    card.appendChild(close);
    // the renderer clears its host, so the page paints into an inner body
    // and the ✕ survives every repaint (the pen cup card's own shape)
    var body = document.createElement('div');
    body.id = 'manage-librarian-card-body';
    card.appendChild(body);
    screen.appendChild(card);
    // ⛔ NO SECOND STATUS READ. `refreshLibrarianSettings` already fetched
    // this visit's answer and parked it on LIBRARIAN.status; a fetch per tap
    // would be a second source for one truth, and the two could disagree.
    fillLibrarianDetail(body, LIBRARIAN.status);
  }

