  ASK_VALUE_KEYS[ASK_KEY_SOURCES] = true;
  ASK_VALUE_KEYS[ASK_KEY_NAME] = true;
  ASK_VALUE_KEYS[ASK_ROSTER_KEY] = true;
  ASK_VALUE_KEYS[ASK_KEY_VOICE] = true;
  ASK_VALUE_KEYS[ASK_KEY_BATCH] = true;

  // The three routes a validated change list can take. MACHINE TOKENS, never
